import {canvasNodeSize,canvasBounds,wrapCanvasText} from './research-canvas-model.js';
export const xml=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
export function canvasPalette(root=document.documentElement){const css=getComputedStyle(root),get=(name,fallback)=>css.getPropertyValue(name).trim()||fallback;return{paper:get('--canvas','#f8f9fb'),surface:get('--surface','#ffffff'),ink:get('--ink','#263a48'),muted:get('--muted','#718091'),line:get('--line','#d8e1e8'),accent:get('--teal','#476f83'),gold:get('--warning','#a27c3f'),blue:'#3c73a6',purple:'#8262a3',green:'#4b8974',red:'#b86a64',gray:'#7d8895',font:get('--sans',"'Segoe UI', 'Microsoft YaHei', sans-serif")};}
function shape(node,w,h,c,fill){const common=`fill="${xml(fill)}" stroke="${xml(c)}" stroke-width="1.5"`;if(node.shape==='ellipse')return`<ellipse rx="${w/2}" ry="${h/2}" ${common}/>`;if(node.shape==='diamond')return`<path d="M0 ${-h/2} L${w/2} 0 L0 ${h/2} L${-w/2} 0 Z" ${common}/>`;if(node.shape==='hexagon')return`<path d="M${-w/2+18} ${-h/2} H${w/2-18} L${w/2} 0 L${w/2-18} ${h/2} H${-w/2+18} L${-w/2} 0 Z" ${common}/>`;return`<rect x="${-w/2}" y="${-h/2}" width="${w}" height="${h}" rx="${node.shape==='rect'?2:12}" ${common}/>`;}
function endpoint(a,b){const size=canvasNodeSize(a),dx=b.x-a.x,dy=b.y-a.y,w=size.width/2+3,h=size.height/2+3;let t;if(a.shape==='ellipse')t=1/Math.sqrt(dx*dx/(w*w)+dy*dy/(h*h));else if(a.shape==='diamond')t=1/(Math.abs(dx)/w+Math.abs(dy)/h);else t=Math.min(w/Math.max(.001,Math.abs(dx)),h/Math.max(.001,Math.abs(dy)));return{x:a.x+dx*t,y:a.y+dy*t};}
export function canvasEdgeGeometry(a,b,board){const p=endpoint(a,b),q=endpoint(b,a);if(!Number.isFinite(p.x+q.x+p.y+q.y))return{path:`M${a.x},${a.y} L${b.x},${b.y}`,x:a.x,y:a.y};if(board.layout==='mindmap'){if(board.direction==='down'){const my=(p.y+q.y)/2;return{path:`M${p.x},${p.y} C${p.x},${my} ${q.x},${my} ${q.x},${q.y}`,x:(p.x+q.x)/2,y:my};}const mx=(p.x+q.x)/2;return{path:`M${p.x},${p.y} C${mx},${p.y} ${mx},${q.y} ${q.x},${q.y}`,x:mx,y:(p.y+q.y)/2};}return{path:`M${p.x},${p.y} L${q.x},${q.y}`,x:(p.x+q.x)/2,y:(p.y+q.y)/2};}
export function canvasContent(board,palette,selected='',interactive=false){
 const p=palette,byId=new Map(board.nodes.map(n=>[n.id,n])),groups=[];
 for(const name of new Set(board.nodes.map(n=>n.group).filter(Boolean))){const b=canvasBounds({nodes:board.nodes.filter(n=>n.group===name)});groups.push(`<g class="rc-group"><rect x="${b.x+40}" y="${b.y+28}" width="${b.width-80}" height="${b.height-50}" rx="16" fill="${xml(p.accent)}" fill-opacity=".045" stroke="${xml(p.line)}" stroke-dasharray="6 5"/><text x="${b.x+55}" y="${b.y+49}" font-size="12" fill="${xml(p.muted)}">${xml(name)}</text></g>`);}
 const defs=`<defs><marker id="rc-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M1 1 L9 5 L1 9" fill="none" stroke="${xml(p.muted)}" stroke-width="1.5"/></marker></defs>`;
 const edges=board.edges.map(e=>{const a=byId.get(e.source),b=byId.get(e.target);if(!a||!b)return'';const g=canvasEdgeGeometry(a,b,board),active=selected===e.id;return`<g ${interactive?`data-rc-edge="${xml(e.id)}" tabindex="0" role="button" aria-label="连线 ${xml(e.label||a.text+' 到 '+b.text)}"`:''} class="rc-edge"><path d="${g.path}" fill="none" stroke="transparent" stroke-width="18"/><path d="${g.path}" fill="none" stroke="${xml(active?p.accent:p.muted)}" stroke-opacity="${active?1:.65}" stroke-width="${active?2.6:1.6}" ${e.dashed?'stroke-dasharray="7 5"':''} ${e.arrow?'marker-end="url(#rc-arrow)"':''}/>${e.label?`<text x="${g.x}" y="${g.y-9}" text-anchor="middle" font-size="12" fill="${xml(p.muted)}" stroke="${xml(p.paper)}" stroke-width="5" paint-order="stroke">${xml(e.label)}</text>`:''}</g>`;}).join('');
 const nodes=board.nodes.map(n=>{const s=canvasNodeSize(n),c=p[n.color]||n.color,active=n.id===selected,top=-s.height/2+22,image=n.image?board.assets[n.image]:null;return`<g ${interactive?`data-rc-node="${xml(n.id)}" tabindex="0" role="button" aria-label="${xml(n.text)}" aria-pressed="${active}"`:''} class="rc-node${active?' is-selected':''}" transform="translate(${n.x} ${n.y})"><title>${xml(n.text)}${n.note?'\n'+xml(n.note.slice(0,1500)):''}</title>${active?`<rect x="${-s.width/2-5}" y="${-s.height/2-5}" width="${s.width+10}" height="${s.height+10}" rx="17" fill="none" stroke="${xml(p.accent)}" stroke-opacity=".35" stroke-width="2" stroke-dasharray="4 4"/>`:''}${shape(n,s.width,s.height,c,p.surface)}${image?`<defs><clipPath id="rc-image-${xml(n.id)}">${shape(n,s.width,s.height,'none','#fff')}</clipPath></defs><image clip-path="url(#rc-image-${xml(n.id)})" href="${xml(image.data)}" x="${-s.width/2+20}" y="${top-8}" width="${s.width-40}" height="112" preserveAspectRatio="xMidYMid meet"/>`:''}<text text-anchor="middle" font-size="16" font-weight="${active?600:400}" fill="${xml(p.ink)}">${s.lines.map((line,i)=>`<tspan x="0" y="${image?top+125+i*22:-(s.lines.length-1)*11-(n.paperId||n.tag||n.note?7:0)+i*20+5}">${xml(line)}</tspan>`).join('')}</text>${n.paperId||n.tag||n.note?`<text x="0" y="${s.height/2-13}" text-anchor="middle" font-size="10.5" fill="${xml(c)}">${n.paperId?'文献已关联':n.tag?'# '+xml(n.tag):'附有研究笔记'}${n.paperId&&n.note?' · 笔记':''}</text>`:''}</g>`;}).join('');
 return defs+groups.join('')+edges+nodes;
}
export function exportCanvasSVG(board,palette){const b=canvasBounds(board),w=Math.ceil(b.width),h=Math.ceil(b.height+60);if(w>24000||h>24000)throw Error('画布范围过大，请先自动布局后再导出。');return`<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="${b.x} ${b.y-60} ${w} ${h}" style="font-family:${xml(palette.font)}"><rect x="${b.x}" y="${b.y-60}" width="${w}" height="${h}" fill="${xml(palette.paper)}"/><text x="${b.x+32}" y="${b.y-22}" font-size="20" font-weight="600" fill="${xml(palette.ink)}">${xml(board.name)}</text>${canvasContent(board,palette)}</svg>`;}
